import 'package:sticky_and_expandable_list/sticky_and_expandable_list.dart';

class ExampleSection implements ExpandableListSection<String> {
  final String title;
  final List<String> items;
  bool _expanded = false;
  ExampleSection(this.title, this.items);
  @override
  bool get isExpanded => _expanded;
  @override
  set isExpanded(bool value) => _expanded = value;
}

final sections = [
  ExampleSection('Fruits', ['Apple', 'Banana']),
  ExampleSection('Vegetables', ['Carrot', 'Lettuce']),
];

ExpandableListView(
  builder: SliverExpandableChildDelegate<String, ExampleSection>(
    sectionList: sections,
    headerBuilder: (ctx, sectionIndex, _) => Text(sections[sectionIndex].title),
    itemBuilder: (ctx, sectionIndex, itemIndex, _) {
      final item = sections[sectionIndex].items[itemIndex];
      return ListTile(title: Text(item));
    },
  ),
);
